steps.command:
mkdir -p "$HOME/.hermes"
touch "$HOME/.hermes/.env"
chmod 600 "$HOME/.hermes/.env"
sed -i '/^HERMES_DASHBOARD_BASIC_AUTH_/d' "$HOME/.hermes/.env"
{
  printf 'HERMES_DASHBOARD_BASIC_AUTH_USERNAME=%s\n' 'admin'
  printf 'HERMES_DASHBOARD_BASIC_AUTH_PASSWORD=%s\n' {{.dashboardPassword}}
  printf 'HERMES_DASHBOARD_BASIC_AUTH_SECRET=%s\n' "$(openssl rand -base64 32 2>/dev/null || head -c 32 /dev/urandom | base64)"
} >> "$HOME/.hermes/.env"
echo '已写入 ~/.hermes/.env（用户名 admin + 密码 + 固定会话签名，权限 600）'
